// === Tab: mySketch ===
//Cube thene WCCC - surface sneks

//making paths within a 3d grid, such that it renders a cube. Paths try to fill out the available area on the 2d faces of a cube. When the whole surface is claimed and they cannot
//find a path they go deeper one layer into the cube, and fill out the newly available surfaces of the nested cube. 
//removing older lines (controlled by lineTrimLength) greatly improves performance but the cube shape is less apparent. 


const gridSize = 10;  //distance between grid points
let cubeFaceSize = 400;  //largest size cube
let cols = 60;  //size of claims array
let cpts;
let cfaces;

let nextFacesU;
let nextFacesV;
let prevFacesU;
let prevFacesV;

let lockedAxis;

let cubeCursors = [];

let claims = [];

let lineTrimLength = 100;  //maximum size line to keep (0 is unlimited)

function setup() {
	createCanvas(windowWidth, windowHeight, WEBGL);
	background(100);

	buildCubePoints(cubeFaceSize);
	initClaimMap();

	strokeWeight(2);

	for (let i = 0; i < 6; i++){
		let c3d = new AxisCursor(i, cubeFaceSize);
		cubeCursors.push(c3d);
	}
}

function initClaimMap() {
	claims = [];
	for (let p = 0; p < cols; p++) {
		claims[p] = [];
		for (let j = 0; j < cols; j++) {
			claims[p][j] = [];
			for (let i = 0; i < cols; i++) {
				claims[p][j][i] = 0;
			}
		}
	}
}

function buildCubePoints(cubeSize) {
	let halfFace = cubeSize / 2;
	cpts = [];
	cpts.push(createVector(-halfFace, -halfFace, halfFace)); //rear upper left, 0
	cpts.push(createVector(-halfFace, -halfFace, -halfFace)); //rear upper right, 1
	cpts.push(createVector(-halfFace, halfFace, -halfFace)); //rear lower right, 2
	cpts.push(createVector(-halfFace, halfFace, halfFace)); //rear lower left, 3
	cpts.push(createVector(halfFace, -halfFace, halfFace)); //front upper left, 4
	cpts.push(createVector(halfFace, -halfFace, -halfFace)); //front upper right, 5
	cpts.push(createVector(halfFace, halfFace, -halfFace)); //front lower right, 6
	cpts.push(createVector(halfFace, halfFace, halfFace)); //front lower left, 7
	cfaces = [];
	cfaces.push([cpts[4], cpts[5], cpts[6], cpts[7]]); //0  front x plane
	cfaces.push([cpts[5], cpts[1], cpts[2], cpts[6]]); //1  rear z plane
	cfaces.push([cpts[1], cpts[0], cpts[3], cpts[2]]); //2  rear x plane
	cfaces.push([cpts[0], cpts[4], cpts[7], cpts[3]]); //3  front z plane
	cfaces.push([cpts[0], cpts[1], cpts[5], cpts[4]]); //4  top y plane
	cfaces.push([cpts[3], cpts[2], cpts[6], cpts[7]]); //5  bottom y plane

	nextFacesU = [1, 2, 3, 0, 1, 1];
	nextFacesV = [5, 5, 5, 5, 0, 0];
	prevFacesU = [3, 0, 1, 2, 3, 3];
	prevFacesV = [4, 4, 4, 4, 2, 2];

	lockedAxis = ['X', 'Z', 'X', 'Z', 'Y', 'Y'];
}

function getFaceForSize(faceid, cubeSize){
	let halfFace = cubeSize / 2;
	let cpts2 = [];
	cpts2.push(createVector(-halfFace, -halfFace, halfFace)); //rear upper left, 0
	cpts2.push(createVector(-halfFace, -halfFace, -halfFace)); //rear upper right, 1
	cpts2.push(createVector(-halfFace, halfFace, -halfFace)); //rear lower right, 2
	cpts2.push(createVector(-halfFace, halfFace, halfFace)); //rear lower left, 3
	cpts2.push(createVector(halfFace, -halfFace, halfFace)); //front upper left, 4
	cpts2.push(createVector(halfFace, -halfFace, -halfFace)); //front upper right, 5
	cpts2.push(createVector(halfFace, halfFace, -halfFace)); //front lower right, 6
	cpts2.push(createVector(halfFace, halfFace, halfFace)); //front lower left, 7
	switch(faceid){
		case 0:
			return [cpts2[4], cpts2[5], cpts2[6], cpts2[7]]; //0  front x plane
		case 1:
			return [cpts2[5], cpts2[1], cpts2[2], cpts2[6]]   //1  rear z plane
		case 2:
			return [cpts2[1], cpts2[0], cpts2[3], cpts2[2]];  //2  rear x plane
		case 3:
			return [cpts2[0], cpts2[4], cpts2[7], cpts2[3]];  //3  front z plane
		case 4:
			return [cpts2[0], cpts2[1], cpts2[5], cpts2[4]];  //4  top y plane
		case 5:
			return [cpts2[3], cpts2[2], cpts2[6], cpts2[7]];  //5  bottom y plane
	}


}




function draw() {
	background(0);

	let x = 400 * cos(frameCount * 0.01);

	// Orbit the camera around the box.
	camera(x, -400, 800);


	noFill();
	stroke(255);
	for (let i = 0; i < cubeCursors.length; i++){
		let cc = cubeCursors[i];
		cc.move();
		cc.render();
	}


}

function snapPointToGrid(inpt){
	let subx = floor(inpt.x / gridSize);
	let suby = floor(inpt.y / gridSize);
	let subz = floor(inpt.z / gridSize);
	inpt.x = subx * gridSize;
	inpt.y = suby * gridSize;
	inpt.z = subz * gridSize;
	return inpt;

}

function getCoordinateFace(qFace, qSize=200){
	let fbounds = getBoundsFace(qFace, qSize);
	let px = fbounds.minx + random(fbounds.maxx - fbounds.minx);
	let py = fbounds.miny + random(fbounds.maxy - fbounds.miny);
	let pz = fbounds.minz + random(fbounds.maxz - fbounds.minz);
	let pt = createVector(px, py, pz);
	return snapPointToGrid(pt);


}

function getBoundsFace(qface, qSize=200) {
	//let facepts = cfaces[qface];
	let facepts = getFaceForSize(qface, qSize);
	let minx = 100000;
	let maxx = -100000;
	let miny = 100000;
	let maxy = -100000;
	let minz = 100000;
	let maxz = -100000;
	for (let i = 0; i < facepts.length; i++) {
		let pt = facepts[i];
		if (pt.x > maxx) {
			maxx = pt.x;
		}
		if (pt.y > maxy) {
			maxy = pt.y;
		}
		if (pt.z > maxz) {
			maxz = pt.z;
		}
		if (pt.x < minx) {
			minx = pt.x;
		}
		if (pt.y < miny) {
			miny = pt.y;
		}
		if (pt.z < minz) {
			minz = pt.z;
		}
	}
	return {
		minx: minx,
		maxx: maxx,
		miny: miny,
		maxy: maxy,
		minz: minz,
		maxz: maxz
	};
}

class AxisCursor {
	constructor(inface, incubesize) {
		this.onFace = inface;
		this.cursor = getCoordinateFace(inface, incubesize);
		this.pathx = [this.cursor.x]
		this.pathy = [this.cursor.y]
		this.pathz = [this.cursor.z]
		this.dx = 0;
		this.dy = 0;
		this.dx = 0;
		this.faceBounds = getBoundsFace(inface, incubesize);
		this.distInDir = 0;
		this.stuck = 0;
		this.cubeSize = incubesize;


		let locked = lockedAxis[inface];
		if (locked == 'X') {
			if (random(1) > 0.5) {
				this.dy = gridSize;
			} else {
				this.dz = gridSize;
			}
		} else if (locked == 'Y') {
			if (random(1) > 0.5) {
				this.dx = gridSize;
			} else {
				this.dz = gridSize;
			}
		} else {
			if (random(1) > 0.5) {
				this.dx = gridSize;
			} else {
				this.dy = gridSize;
			}
		}
	}

	render() {
		beginShape();
		for (let i = 0; i < this.pathx.length; i++) {
			let px = this.pathx[i];
			let py = this.pathy[i];
			let pz = this.pathz[i];

			vertex(px, py, pz);
		}
		endShape();
	}

	interiorDrop() {
		//migrate path to cube face surface one gridspace deeper
		//strange glitches when paths cross through center to other side- paths tunnel out and escape cube
		this.pathx.push(this.cursor.x);
		this.pathy.push(this.cursor.y);
		this.pathz.push(this.cursor.z);
		let locked = lockedAxis[this.onFace];
		if (locked == 'X') {
			if (this.cursor.x > 0) {
				this.cursor.x -= gridSize;
			} else {
				this.cursor.x += gridSize;
			}
		} else if (locked == 'Y') {
			if (this.cursor.y > 0) {
				this.cursor.y -= gridSize;
			} else {
				this.cursor.y += gridSize;
			}
		} else {
			if (this.cursor.z > 0) {
				this.cursor.z -= gridSize;
			} else {
				this.cursor.z += gridSize;
			}
		}
		this.pathx.push(this.cursor.x);
		this.pathy.push(this.cursor.y);
		this.pathz.push(this.cursor.z);
	}

	newFace(nfaceid) {
		let lockedPrev = lockedAxis[this.onFace];
		let lockedNow = lockedAxis[nfaceid];

		this.onFace = nfaceid;
		this.faceBounds = getBoundsFace(nfaceid, this.cubeSize);
	}

	move() {

		let min_val = 0 -  (this.cubeSize / 2);
		let max_val = (this.cubeSize / 2);


		let lastx = this.cursor.x;
		let lasty = this.cursor.y;
		let lastz = this.cursor.z;

		this.cursor.x += this.dx;
		this.cursor.y += this.dy;
		this.cursor.z += this.dz;

		if (this.cursor.x > this.faceBounds.maxx) {
			let over = this.cursor.x - this.faceBounds.maxx;
			this.cursor.x = this.faceBounds.maxx;
			this.newFace(0);
			let dxv = this.dx;
			if (this.cursor.z == max_val) {
				this.dz = -dxv;
			} else if (this.cursor.y == max_val) {
				this.dy = -dxv;
			} else if (this.cursor.y == min_val) {
				this.dy = dxv;
			} else if (this.cursor.z == min_val) {
				this.dz = dxv;
			}
			this.dx = 0;
		} else if (this.cursor.x < this.faceBounds.minx) {
			let over = this.faceBounds.minx - this.cursor.x;
			this.cursor.x = this.faceBounds.minx;
			this.newFace(2);
			let dxv = this.dx;
			if (this.cursor.z == max_val) {
				this.dz = dxv;
			} else if (this.cursor.z == min_val) {
				this.dz = -dxv;
			} else if (this.cursor.y == max_val) {
				this.dy = dxv;
			} else if (this.cursor.y == min_val) {
				this.dy = -dxv;
			}
			this.dx = 0;
		}
		if (this.cursor.y > this.faceBounds.maxy) {
			let over = this.cursor.y - this.faceBounds.maxy;
			this.cursor.y = this.faceBounds.maxy;
			this.newFace(5);
			let dyv = this.dy;
			if (this.cursor.z == max_val) {
				this.dz = -dyv;
			} else if (this.cursor.z == min_val) {
				this.dz = dyv;
			} else if (this.cursor.x == max_val) {
				this.dx = -dyv;
			} else if (this.cursor.x == min_val) {
				this.dx = dyv;
			}
			this.dy = 0;
		} else if (this.cursor.y < this.faceBounds.miny) {
			let over = this.faceBounds.miny - this.cursor.y;
			this.cursor.y = this.faceBounds.miny;
			this.newFace(4);
			let dyv = this.dy;
			if (this.cursor.z == max_val) {
				this.dz = dyv;
			} else if (this.cursor.z == min_val) {
				this.dz = -dyv;
			} else if (this.cursor.x == max_val) {
				this.dx = dyv;
			} else if (this.cursor.x == min_val) {
				this.dx = -dyv;
			}
			this.dy = 0;
		}
		if (this.cursor.z > this.faceBounds.maxz) {
			let over = this.cursor.z - this.faceBounds.maxz;
			this.cursor.z = this.faceBounds.maxz;
			this.newFace(3);
			let dzv = this.dz;
			if (this.cursor.y == max_val) {
				this.dy = -dzv;
			} else if (this.cursor.y == min_val) {
				this.dy = dzv;
			} else if (this.cursor.x == max_val) {
				this.dx = -dzv;
			} else if (this.cursor.x == min_val) {
				this.dx = dzv;
			}
			this.dz = 0;
		} else if (this.cursor.z < this.faceBounds.minz) {
			let over = this.faceBounds.minz - this.cursor.z;
			this.cursor.z = this.faceBounds.minz;
			this.newFace(1);
			let dzv = this.dz;
			if (this.cursor.y == max_val) {
				this.dy = dzv;
			} else if (this.cursor.y == min_val) {
				this.dy = -dzv;
			} else if (this.cursor.x == max_val) {
				this.dx = dzv;
			} else if (this.cursor.x == min_val) {
				this.dx = -dzv;
			}
			this.dz = 0;
		}

		let gx = floor(this.cursor.x / gridSize) + 20;
		let gy = floor(this.cursor.y / gridSize) + 20;
		let gz = floor(this.cursor.z / gridSize) + 20;

		let canGo = false;

		if (gx >= 0 && gx < cols && gy >= 0 && gy < cols && gz >= 0 && gz < cols) {
			if (claims[gx][gy][gz] == 0) {
				canGo = true;
				claims[gx][gy][gz] = 1;
			}

		}

		if (canGo) {
			this.stuck = 0;
			this.pathx.push(this.cursor.x);
			this.pathy.push(this.cursor.y);
			this.pathz.push(this.cursor.z);
			if (lineTrimLength > 0){
				if (this.pathx.length > lineTrimLength){
					this.pathx.shift();
					this.pathy.shift();
					this.pathz.shift();
				}
			}

			let blockedAhead = false;

			if (this.dx > 0) {
				if (gx < cols - 1) {
					blockedAhead = claims[gx + 1][gy][gz] == 1;
				}
			} else if (this.dx < 0) {
				if (gx > 0) {
					blockedAhead = claims[gx - 1][gy][gz] == 1;
				}
			} else if (this.dy > 0) {
				if (gy < cols - 1) {
					blockedAhead = claims[gx][gy + 1][gz] == 1;
				}
			} else if (this.dy < 0) {
				if (gy > 0) {
					blockedAhead = claims[gx][gy - 1][gz] == 1;
				}
			} else if (this.dz > 0) {
				if (gz < cols - 1) {
					blockedAhead = claims[gx][gy][gz + 1] == 1;
				}
			} else if (this.dz < 0) {
				if (gz > 0) {
					blockedAhead = claims[gx][gy][gz - 1] == 1;
				}

			}

			this.distInDir++;

			if (this.distInDir > 3 || blockedAhead) {
				if (random(1) > 0.65 || blockedAhead) {
					let prevdir;
					if (this.dx != 0) {
						prevdir = 'X';
					} else if (this.dy != 0) {
						prevdir = 'Y'
					} else {
						prevdir = 'Z';
					}
					this.dx = 0;
					this.dy = 0;
					this.dz = 0;
					this.distInDir = 0;
					let locked = lockedAxis[this.onFace];
					if (locked == 'X') {
						if (prevdir == 'Y') {
							if (random(1) > 0.5) {
								this.dz = gridSize;
							} else {
								this.dz = -gridSize;
							}
						} else {
							if (random(1) > 0.5) {
								this.dy = gridSize;
							} else {
								this.dy = -gridSize;
							}
						}

					} else if (locked == 'Y') {
						if (prevdir == 'X') {
							if (random(1) > 0.5) {
								this.dz = gridSize;
							} else {
								this.dz = -gridSize;
							}
						} else {
							if (random(1) > 0.5) {
								this.dx = gridSize;
							} else {
								this.dx = -gridSize;
							}
						}

					} else {
						if (prevdir == 'X') {
							if (random(1) > 0.5) {
								this.dy = gridSize;
							} else {
								this.dy = -gridSize;
							}
						} else {
							if (random(1) > 0.5) {
								this.dx = gridSize;
							} else {
								this.dx = -gridSize;
							}
						}

					}
				}
			}
		} else {
			this.stuck++;
			if (this.stuck > 10) {
				//if nowhere to path to on current face, go deeper one level to the surface underneath
				this.stuck = 0;
				this.cubeSize -= (gridSize * 2);
				this.interiorDrop();
				this.faceBounds = getBoundsFace(this.onFace, this.cubeSize);
			} else {

				this.cursor.x = lastx;
				this.cursor.y = lasty;
				this.cursor.z = lastz;
				let prevdir;
				if (this.dx != 0) {
					prevdir = 'X';
				} else if (this.dy != 0) {
					prevdir = 'Y'
				} else {
					prevdir = 'Z';
				}
				this.dx = 0;
				this.dy = 0;
				this.dz = 0;
				this.distInDir = 0;
				let locked = lockedAxis[this.onFace];
				if (locked == 'X') {
					if (prevdir == 'Y') {
						if (random(1) > 0.5) {
							this.dz = gridSize;
						} else {
							this.dz = -gridSize;
						}
					} else {
						if (random(1) > 0.5) {
							this.dy = gridSize;
						} else {
							this.dy = -gridSize;
						}
					}

				} else if (locked == 'Y') {
					if (prevdir == 'X') {
						if (random(1) > 0.5) {
							this.dz = gridSize;
						} else {
							this.dz = -gridSize;
						}
					} else {
						if (random(1) > 0.5) {
							this.dx = gridSize;
						} else {
							this.dx = -gridSize;
						}
					}

				} else {
					if (prevdir == 'X') {
						if (random(1) > 0.5) {
							this.dy = gridSize;
						} else {
							this.dy = -gridSize;
						}
					} else {
						if (random(1) > 0.5) {
							this.dx = gridSize;
						} else {
							this.dx = -gridSize;
						}
					}
				}
			}
		}

	}

}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

// 1.7 免疫機器學習與人臉偵測 (ml5.js, clmtrackr, aiptag, lime) 缺失與內部指標 null 導致的崩潰 (修復 ml5.js .features of null 報錯)
if (typeof window.clm === 'undefined') {
    window.clm = {
        tracker: class {
            init() {}
            start() {}
            track() { return []; }
            getCurrentPosition() { return []; }
            getScore() { return 0; }
        }
    };
}
if (typeof window.ml5 === 'undefined') {
    const ml5MockObj = {
        detectStart: function() {},
        features: { get: function() { return []; } },
        on: function() {},
        ready: Promise.resolve(),
        loadModel: Promise.resolve()
    };
    window.ml5 = {
        bodypix: function() { return ml5MockObj; },
        faceapi: function() { return ml5MockObj; },
        handpose: function() { return ml5MockObj; },
        poseNet: function() { return ml5MockObj; },
        objectDetector: function() { return ml5MockObj; }
    };
}
if (typeof window.aiptag === 'undefined') { window.aiptag = {}; }
if (typeof window.lime === 'undefined') { window.lime = {}; }

// 1.8 免疫 3D 物理引擎與高階渲染 (THREE.Group, Tone.js, p5.asciify, REGL, Voronoi, PolyK, qrcode, P5Capture) 缺失導致的崩潰
if (typeof window.THREE === 'undefined') {
    window.THREE = {
        Group: class {},
        Scene: class {},
        PerspectiveCamera: class {},
        WebGLRenderer: class { setSize() {} },
        Mesh: class {},
        BoxGeometry: class {}
    };
}
if (typeof window.Tone === 'undefined') {
    window.Tone = {
        Player: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Players: class { play() {} start() {} stop() {} connect() {} toDestination() {} },
        Sampler: class { triggerAttackRelease() {} connect() {} toDestination() {} },
        Sequence: class { start() {} stop() {} },
        Transport: { start: function() {}, stop: function() {}, bpm: { value: 120 } }
    };
}
if (typeof window.createREGL === 'undefined') {
    window.createREGL = function() {
        const regl = function() {};
        regl.texture = function() { return { resize: function() {} }; };
        regl.buffer = function() { return { subdata: function() {} }; };
        regl.framebuffer = function() { return { use: function(cb) { cb(); } }; };
        return regl;
    };
}
if (typeof window.Voronoi === 'undefined') {
    window.Voronoi = class {
        compute() { return { cells: [], edges: [] }; }
    };
}
if (typeof window.qrcode === 'undefined') {
    window.qrcode = function(data) {
        return {
            createImgTag: function() { return ""; },
            createTableTag: function() { return ""; },
            createSvgTag: function() { return ""; }
        };
    };
    window.qrcode.stringToBytes = function(s) { return []; };
}
if (typeof window.PolyK === 'undefined') {
    window.PolyK = {
        Slice: function() { return []; },
        Triangulate: function() { return []; },
        getArea: function() { return 0; }
    };
}
if (typeof window.P5Capture === 'undefined') {
    window.P5Capture = {
        getInstance: function() {
            return { start: function() {}, stop: function() {}, setFormat: function() {} };
        },
        setDefaultOptions: function() {}
    };
}

// 1.9 免疫 OPC (OpenProcessing Controller) 與 WebGL 內部 setUniform 崩潰
if (typeof window.OPC === 'undefined') {
    window.OPC = {
        title: function() {},
        slider: function() {},
        button: function() {},
        toggle: function() {},
        color: function() {}
    };
}
if (typeof p5 !== 'undefined' && p5.Shader) {
    const origSetUniform = p5.Shader.prototype.setUniform;
    p5.Shader.prototype.setUniform = function(name, val) {
        if (!this) return this;
        try {
            return origSetUniform.call(this, name, val);
        } catch(e) {
            return this;
        }
    };
}

// 1.95 免疫某些特定遊戲模組對 parent / maeExportApis_ 或是唯讀屬性的寫入崩潰
try {
  if (typeof window.parent !== 'undefined') {
    if (!window.parent.maeExportApis_) {
      try {
        window.parent.maeExportApis_ = function() {};
      } catch(e) {}
    }
  }
} catch(e) {}

// 1.96 免疫 textmode 缺失以及 loadSVG / p5.SVG 插件型別拋錯
if (typeof textmode === 'undefined') { window.textmode = function() {}; }
if (typeof MAT === 'undefined') { window.MAT = []; }
if (typeof SIDES === 'undefined') { window.SIDES = 4; }
if (typeof GRIDBOX === 'undefined') { window.GRIDBOX = 10; }
if (typeof COLUMNS === 'undefined') { window.COLUMNS = 5; }
if (typeof tileSize === 'undefined') { window.tileSize = 30; }
if (typeof mouseTileX === 'undefined') { window.mouseTileX = 0; }
if (typeof p5 !== 'undefined') {
  if (!p5.prototype.loadSVG) {
    p5.prototype.loadSVG = function(path, success, failure) {
      if (success) success({});
      return {};
    };
  }
  // 免疫 window.VERSION 唯讀寫入錯誤
  try {
    Object.defineProperty(window, 'VERSION', {
      value: "p5-stub",
      writable: true,
      configurable: true
    });
  } catch(e) {}
}

// 2. 圖片與非同步資產載入後備自癒護欄
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origLoadImage === 'undefined') { window._origLoadImage = p5.prototype.loadImage; }
    p5.prototype.loadImage = function(path, successCallback, failureCallback) {
        if (typeof path !== 'string' || path.startsWith('http') || (path.startsWith('data:') === false && path.indexOf('.') === -1)) {
            // 當發現是遠端 URL、相對路徑或格式無副檔名時，使用 1x1 灰色 GIF 的 Base64 代替，防止渲染死鎖與 CORS 錯誤
            const dummyPath = "data:image/gif;base64,R0lGODlhAQABAIAAAAAAAP///yH5BAEAAAAALAAAAAABAAEAAAIBRAA7";
            return window._origLoadImage.call(this, dummyPath, successCallback, failureCallback);
        }
        return window._origLoadImage.call(this, path, successCallback, failureCallback);
    };

    // 修正 img.loadPixels / img.resize 缺失與未非同步載入完成呼叫
    if (!p5.Image.prototype.loadPixels) { p5.Image.prototype.loadPixels = function() { return this; }; }
    if (!p5.Image.prototype.resize) { p5.Image.prototype.resize = function() { return this; }; }
    if (!p5.Image.prototype.get) { p5.Image.prototype.get = function() { return [0,0,0,255]; }; }
    if (!p5.Image.prototype.width) {
        Object.defineProperty(p5.Image.prototype, 'width', {
            get: function() { return this._width || 1280; },
            set: function(v) { this._width = v; }
        });
    }
    if (!p5.Image.prototype.height) {
        Object.defineProperty(p5.Image.prototype, 'height', {
            get: function() { return this._height || 720; },
            set: function(v) { this._height = v; }
        });
    }

    // 修正 p5.Graphics / p5.Renderer / Element.prototype.style
    if (p5.Graphics && p5.Graphics.prototype) {
        if (!p5.Graphics.prototype.loadPixels) { p5.Graphics.prototype.loadPixels = function() { return this; }; }
    }
}

// 2.2 修正 p5.Table / loadTable / getRowCount 缺失與錯誤
if (typeof p5 !== 'undefined' && p5.Table) {
    if (!p5.Table.prototype.getRowCount) { p5.Table.prototype.getRowCount = function() { return 0; }; }
}

// 3. 修正 3D 渲染圖層 WebGL 與 Canvas 2D 上下文屬性缺失
if (typeof p5 !== 'undefined' && p5.prototype) {
    if (typeof window._origGet === 'undefined') { window._origGet = p5.prototype.get; }
    p5.prototype.get = function(...args) {
        if (!this || this.width === 0 || this.height === 0) {
            return [0,0,0,255];
        }
        try {
            return window._origGet.apply(this, args);
        } catch(e) {
            return [0,0,0,255];
        }
    };
}

